INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'ASEAN $10,000 Early Acceptance Scholarship', 'This early acceptance scholarship is awarded to talented international students from the ASEAN region who intend to pursue a coursework degree at Macquarie University, offsetting approximately 25% of their annual tuition fees. Among one of the most g', 'AUD $10000/year', 'https://www.mq.edu.au/study/admissions-and-entry/scholarships/international/asean-10-000-early-acceptance-scholarship', '2026-11-05 10:40:16', '2026-11-05 10:40:16' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00002J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'ASEAN $10,000 Early Acceptance Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'ASEAN Partner Institution Scholarship', 'To recognise the strong relationship between Macquarie University and institutions in the ASEAN region, this ASEAN Partner Scholarship is awarded to prospective students from the region with a quest for knowledge. The scholarship amount is valued up ', 'AUD $15000/year', 'https://www.mq.edu.au/study/admissions-and-entry/scholarships/international/asean-partner-institution-scholarship', '2026-11-05 10:40:16', '2026-11-05 10:40:16' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00002J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'ASEAN Partner Institution Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Bangladesh $10,000 Early Acceptance Scholarship', 'This scholarship offers talented international students from Bangladesh AUD $10,000 per year towards their studies at Macquarie University. The scholarship is available for the full duration of an eligible Bachelor\'s and Master\'s coursework degree. F', 'AUD $10000/year — Applicants will be assessed automatically for this scholarship. Successful candidates will receive the scholarship with their Course Letter of Offer.', 'https://www.mq.edu.au/study/admissions-and-entry/scholarships/international/bangladesh-10-000-early-acceptance-scholarship/', '2026-11-05 10:40:16', '2026-11-05 10:40:16' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00002J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Bangladesh $10,000 Early Acceptance Scholarship') LIMIT 1;
