INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'RMIT University Top-up Scholarship for Vietnam Government (Project 89)', 'This top-up scholarship program is available to talented Vietnamese students aims to address Vietnam\'s future industry and workforce needs, prioritising key research areas such as digital technologies, physics, biotechnologies and energy & environmen', 'a tuition fee scholarship of up to $25,000 USD; a stipend scholarship of $1,120 USD per month; an international return airfare and travel allowances; Overseas Student Health Cover (OSHC) for the time spent in Australia (up to $1,000 USD per year).', 'https://www.rmit.edu.au/scholarships/international-scholarships/vietnam-government-project-89-rmit-scholarship#overview', '2026-11-05 10:40:16', '2026-11-05 10:40:16' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00122A' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'RMIT University Top-up Scholarship for Vietnam Government (Project 89)') LIMIT 1;
