INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, '2026 VU Sydney & Brisbane Global Diversity Scholarship', 'The 2026 VU Sydney and VU Brisbane Diversity Scholarship provides an additional 10% tuition fee reduction for students enrolling in our undergraduate, postgraduate, and higher education diploma programs in IT and Business. This 10% reduction is offer', '10% reduction of the course tuition fee the duration of the course. (Applied in addition to the 22.5% VU Sydney and Brisbane 2026 International Scholarship)', 'https://www.vu.edu.au/vu-sydney/study-at-vu-sydney/vu-sydney-scholarships', '2026-11-05 10:40:16', '2026-11-05 10:40:16' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00124K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = '2026 VU Sydney & Brisbane Global Diversity Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Australia Awards Scholarships', 'Australia Awards scholarships are long-term development awards, offered by the Australian Government and administered by the Department of Foreign Affairs and Trade (DFAT). They aim to contribute to the long-term development needs of Australia\'s part', 'Tuition fees, living allowance, Overseas Student Health Cover and academic support.', 'https://www.vu.edu.au/study-at-vu/fees-scholarships/scholarships/international-scholarships', '2026-11-05 10:40:16', '2026-11-05 10:40:16' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00124K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Australia Awards Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Early Childhood Education International Scholarship (2025)', 'The 2025 Early Childhood Education International Scholarship supports new international students who plan to commence an Early Childhood Education course in 2025. \r\n\r\nDo not miss this incredible opportunity to get a world-class qualification from a g', '-Graduate Diploma in Early Childhood Education (EGEC): 20% tuition fee reduction for the entire standard duration of eligible courses (calculated from the date of commencement to the course end date in the letter of offer). – Only applicable for Febr', 'https://www.vu.edu.au/vu-sydney/study-at-vu-sydney/vu-sydney-scholarships', '2026-11-05 10:40:16', '2026-11-05 10:40:16' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00124K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Early Childhood Education International Scholarship (2025)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'STEM Accommodation Scholarship', 'Enjoy a stress-free start to your studies and save up to $15,500 with the unique STEM Accommodation Scholarship at Victoria University (VU).  Our exciting merit-based scholarship offers eligible international students free accommodation at UniLodge V', 'Successful undergraduate applicants will receive one year (52 weeks) of free accommodation at UniLodge VU, valued at $15,548. / Successful postgraduate applicants will receive six months (26 weeks) of free accommodation at UniLodge VU, valued at $8,5', 'https://www.vu.edu.au/study-at-vu/fees-scholarships/scholarships/international-scholarships', '2026-11-05 10:40:16', '2026-11-05 10:40:16' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00124K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'STEM Accommodation Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'VU Block Model International Scholarship', 'At Victoria University (VU), were committed to supporting your success. Our unique VU Block Model® International Scholarship offers all eligible international students up to 30% off tuition fees for the entire first year. Study well and youll have th', 'Up to 30% off your first year tuition fees – based on merit. Study well and youll have the chance to keep or increase the scholarship for the full duration of your course.', 'https://www.vu.edu.au/study-at-vu/fees-scholarships/scholarships/international-scholarships/vu-block-model-international-scholarship', '2026-11-05 10:40:16', '2026-11-05 10:40:16' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00124K' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'VU Block Model International Scholarship') LIMIT 1;
