INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'A smart CPR feedback device for cardiac arrest (PhD scholarship)', 'This PhD project focuses on developing the first-ever closed-loop cardiopulmonary resuscitation (CPR) feedback device. The device uses non-invasive sensors to measure blood oxygenation in the brain and tells the CPR provider how to adjust their compr', 'AUD $33637/year', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/a-smart-cpr-feedback-device-for-cardiac-arrest-phd-scholarship', '2026-11-05 10:40:16', '2026-11-05 10:40:16' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'A smart CPR feedback device for cardiac arrest (PhD scholarship)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Australia Awards Scholarship', 'As an Australia Awards student you need to attend a five-week Introductory Academic Program (IAP). It’s a chance for you to get help with enrolment, learning skills, language expectations and our technology and teaching systems. You will receive prog', 'See scholarship details', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/australia-awards-scholarship', '2026-11-05 10:40:16', '2026-11-05 10:40:16' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Australia Awards Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Australian South Sea Islander Community Foundation Scholarship', 'The Australian South Sea Islander Community Foundation was established by the Queensland Government in 2001 as a perpetual fund to provide scholarships to Australian South Sea Islander undergraduate students.', 'You will receive an Australian South Sea Islander Community Foundation Scholarship. The value and number of scholarships will vary annually depending on funding. These scholarships are subject to annual funding.', 'http://www.qut.edu.au/study/fees-and-scholarships/scholarships/australian-south-sea-islander-community-foundation-scholarship', '2026-11-05 10:40:16', '2026-11-05 10:40:16' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Australian South Sea Islander Community Foundation Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Bachelor of Arts Impact Scholarship', 'The Bachelor of Arts Impact Scholarship is awarded to high-achieving school leavers and eligible gap year students starting our Bachelor of Arts degree. This scholarship is targeted at high achievers to enable their continued success at QUT through f', 'Up to AUD $15000', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/bachelor-of-arts-impact-scholarship', '2026-11-05 10:40:16', '2026-11-05 10:40:16' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Bachelor of Arts Impact Scholarship') LIMIT 1;
