INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Clayton Adam Florence Wilson Award for Biomechanics and Spine Research', 'The Clayton Adam Florence Wilson Award is available to promote spine research at QUT, and honours the stellar contribution to scientific innovation in spine research made by our former Research Director, Professor Clayton Adam. Clayton joined QUT in ', 'See scholarship details', 'http://www.qut.edu.au/study/fees-and-scholarships/scholarships/CAFW-Award', '2026-11-05 10:40:16', '2026-11-05 10:40:16' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Clayton Adam Florence Wilson Award for Biomechanics and Spine Research') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Data61 PhD Scholarship', 'At CSIRO\'s Data61, we aim to develop top-quality doctoral students who will prosper in careers in Australia’s data-skilled workforce. Our PhD scholarship program provides opportunities for outstanding postgraduate students with demonstrated academic ', 'a full scholarship which includes a base stipend at the Australian Government Research Training (RTP) Program base rate supplemented with a top-up scholarship of $10,000 per annum. Data61 PhD scholarships have a maximum term of 3 years and 6 months.', 'http://www.qut.edu.au/study/fees-and-scholarships/scholarships/data61-phd-scholarship', '2026-11-05 10:40:16', '2026-11-05 10:40:16' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Data61 PhD Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Dynamic soft matter materials PhD scholarship', 'As the successful applicant you will complete your PhD in the field of organic photochemistry for advanced reprogrammable material design.Based in our Science and Engineering Faculty, you will also spend time at our research hub at the Karlsruhe Inst', 'a minimum of $30,000 per year, for 3 yearsa QUT tuition fee sponsorship (for international students).', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/dynamic-soft-matter-materials-phd-scholarship', '2026-11-05 10:40:16', '2026-11-05 10:40:16' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Dynamic soft matter materials PhD scholarship') LIMIT 1;
