INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Equity scholarships scheme', 'The QUT Equity Scholarships Scheme is an application-based scheme offered to students who experience financial difficulty. It is funded by significant contributions from the Learning Potential Fund. The scholarships and bursaries are offered to comme', 'Up to AUD $4200', 'http://www.qut.edu.au/study/fees-and-scholarships/scholarships/equity-scholarships-scheme', '2026-11-05 10:40:16', '2026-11-05 10:40:16' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Equity scholarships scheme') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'International Merit Scholarship', 'A high achievement scholarship for future international undergraduate and postgraduate students.', 'a scholarship to cover 25% of your tuition fees for your first two semesters (one year) of study at QUT, provided you meet the minimum academic standards.', 'http://www.qut.edu.au/study/fees-and-scholarships/scholarships/international-merit-scholarship', '2026-11-05 10:40:16', '2026-11-05 10:40:16' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International Merit Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'International Talent Scholarship', 'A new scholarship for 2026 that covers tuition fees, with eligibility based on your prior academic achievements.', 'You\'ll receive an ongoing scholarship to cover 20% of your tuition fees per semester of study at QUT', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/international-talent-scholarship', '2026-11-05 10:40:16', '2026-11-05 10:40:16' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'International Talent Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Investigation on Bubble Dynamics Under Electric Fields in Water Electrolysis Process', 'We are seeking a PhD candidate to investigate gas bubble dynamics under the influence of electric fields, with a particular focus on applications in electrochemical hydrogen production. The project will examine the physical mechanisms governing bubbl', 'AUD $37010/year', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/investigation-on-bubble-dynamics-under-electric-fields-in-water-electrolysis-process', '2026-11-05 10:40:16', '2026-11-05 10:40:16' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Investigation on Bubble Dynamics Under Electric Fields in Water Electrolysis Process') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'QUT College English Language Concession', 'A tuition fee concession for commencing students from selected countries to study English for Academic Purposes or IELTS Advanced Program at QUT College.', 'A reduction of 25% from the tuition fee of your English for Academic Purposes (EAP) and IELTS Advanced programs at QUT College.', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/qut-college-english-language-concession', '2026-11-05 10:40:16', '2026-11-05 10:40:16' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'QUT College English Language Concession') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'QUT College Merit Scholarship', 'This scholarship is sponsored by QUT College. It is available to international students who have demonstrated academic achievement or can demonstrate how they intend to commit to success in their future studies.', 'A scholarship to cover 25% of the tuition fees for the first semester of your Diploma or Foundation program at QUT International College. An invitation to a Pathway Scholarship ceremony, certificate of recognition, and access to extra-curricular prof', 'http://www.qut.edu.au/study/fees-and-scholarships/scholarships/qut-international-college-pathway-scholarship', '2026-11-05 10:40:16', '2026-11-05 10:40:16' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'QUT College Merit Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'QUT Excellence Scholarship (Academic)', 'The QUT Excellence Scholarship is our premier offering for high achievers. We award more than 130 scholarships annually, worth more than $3.5 million.In addition to the financial support, the program helps you to make the most of your QUT experience ', 'Up to AUD $30000 — scholarships valued at $30,000 each for study in any discipline, scholarships valued at $30,000 each for courses in the Faculty of Science and Faculty of Engineering only.', 'https://www.qut.edu.au/study/fees-and-scholarships/scholarships/excellence-scholarship-academic', '2026-11-05 10:40:16', '2026-11-05 10:40:16' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00213J' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'QUT Excellence Scholarship (Academic)') LIMIT 1;
