INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Academic Scholarship', 'Academic Scholarships are awarded to students who demonstrate outstanding academic potential. The scholarships are open to students in Years 6 and 9 in 2023 and will be offered for Years 7 and 10 in 2024. Applicants will sit the ACER Scholarship Exam', 'The awarding of a scholarship of financial subsidy of each scholarship is determined by the Head of College and the Scholarship Testing Committee. The amount is based on merit and achievement in testing.', 'https://search.studyaustralia.gov.au/scholarship/academic-scholarship/7a2db5ecc5972d90adee7355677eccdc', '2026-11-05 10:40:16', '2026-11-05 10:40:16' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00581G' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Academic Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, '10% Tuition fee discounts', 'A 10% reduction on registered tuition fees will be awarded to University of Tasmania international students who meet the eligibility requirements as outlined in the below bursary or scholarship theme areas.', '10% reduction in registered tuition fees for the duration of the course.', 'https://www.utas.edu.au/study/scholarships-fees-and-costs/international-scholarships/10-tuition-fee-discounts', '2026-11-05 10:40:16', '2026-11-05 10:40:16' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00586B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = '10% Tuition fee discounts') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Australian Government Research Training Program (RTP) Scholarships', 'Awarded competitively to students of exceptional research potential to assist with living costs while undertaking a Higher Degree by Research. Living Allowance', 'Up to AUD $33511 — PhD: 3.5 years FTE. It is important to be aware that the duration of the scholarship is less than the maximum length of candidature, which is 4 years.; Masters: 2 years FTE.', 'https://www.utas.edu.au/research/degrees/scholarships-and-fees', '2026-11-05 10:40:16', '2026-11-05 10:40:16' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00586B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Australian Government Research Training Program (RTP) Scholarships') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Early Acceptance Scholarship', 'This scholarship covers 15% of registered tuition fees for the duration of study up to a maximum of four years. Applicants must have an offer for an eligible course commencing in Summer School or Semester one 2026.', '15% reduction in registered tuition fees for the duration of the course.', 'https://www.utas.edu.au/study/scholarships-fees-and-costs/international-scholarships/early-acceptance-scholarship', '2026-11-05 10:40:16', '2026-11-05 10:40:16' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00586B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Early Acceptance Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Feng Chia University Scholarship', 'This scholarship covers 20% of the registered tuition fees for two years of study in the Bachelor of Global Logistics and Maritime Management (P3E) for applicants from International School of Technology and Management (Business), Feng Chia University', '20% reduction in registered tuition fees for the duration of the course.', 'https://www.utas.edu.au/study/scholarships-fees-and-costs/international-scholarships/fcu-scholarship', '2026-11-05 10:40:16', '2026-11-05 10:40:16' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00586B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Feng Chia University Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Singapore Maritime Academy Scholarship', 'This scholarship covers 20% of registered tuition fees for one year of study in the Bachelor of Global Logistics and Maritime Management (P3E) for applicants from Singapore Maritime Academy.', '20% reduction in registered tuition fees for the duration of the course.', 'https://www.utas.edu.au/study/scholarships-fees-and-costs/international-scholarships/singapore-maritime-academy-scholarship', '2026-11-05 10:40:16', '2026-11-05 10:40:16' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00586B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Singapore Maritime Academy Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Tasmania Graduate Research Scholarship (TGRS)', 'Tasmania Graduate Research Scholarships are available across all research disciplines at the University of Tasmania and will be awarded to applicants with demonstrated research ability.', 'Full-time candidates receive a stipend at the rate of AUD$33,511pa non-taxable (2025 rate, indexed annually); Part-time candidates receive a stipend at the rate of AUD$16,756pa taxable (2025 rate, indexed annually).; Scholarship holders may apply for', 'https://www.utas.edu.au/research/degrees/scholarships-and-fees', '2026-11-05 10:40:16', '2026-11-05 10:40:16' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00586B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Tasmania Graduate Research Scholarship (TGRS)') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Tasmanian International Scholarship', 'The Tasmanian International Scholarship is assessed on academic merit and provides eligible commencing international students with a 25% reduction in registered tuition fees for the duration of their course.', '25% reduction in registered tuition fees for the duration of the course.', 'https://www.utas.edu.au/study/scholarships-fees-and-costs/international-scholarships/tasmanian-international-scholarship', '2026-11-05 10:40:16', '2026-11-05 10:40:16' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00586B' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Tasmanian International Scholarship') LIMIT 1;
INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Australia Awards Scholarships', 'The Australian Government offers Australia Awards Scholarships through the Department of Foreign Affairs and Trade. The scholarships aim to contribute to the developmental needs of Australia\'s partner countries by providing financial support to study', 'What\'s included?; Full tuition fees, Return air travel, Contribution to Living Expenses (CLE), Introductory Academic Program (IAP), Overseas Student Health Cover (OSHC), Pre-course English (PCE) fees–if deemed necessary.', 'https://www.tafensw.edu.au/international/apply/scholarships', '2026-11-05 10:40:16', '2026-11-05 10:40:16' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00591E' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Australia Awards Scholarships') LIMIT 1;
