INSERT INTO `scholarships` (`user_id`, `course_id`, `provider_institution_id`, `scholarship_name`, `scholarship_description`, `scholarship_amount`, `website`, `created_at`, `updated_at`) SELECT 1, 0, pi.`id`, 'Cambridge International Global Scholars Award and Cambridge International Excellence Award', 'We are giving young, high-achieving international students the opportunity to achieve a prestigious scholarship award towards our NEW Cambridge International AS and A Levels program. This is an exceptional opportunity for Year 10 students with a stro', 'The Global Scholar Award: 100% of your first-year tuition fees (value approx. A$39,000). Four available globally.; The Excellence Award: 50% of your first-year tuition fees (value approx. A$19,500). Twelve available globally.', 'https://utscollege.edu.au/au/programs/cambridge/scholarship', '2026-11-05 10:40:16', '2026-11-05 10:40:16' FROM `provider_institution` pi WHERE pi.`cricos_provider_code` = '00859D' AND NOT EXISTS (SELECT 1 FROM `scholarships` sc WHERE sc.`provider_institution_id` = pi.`id` AND sc.`scholarship_name` = 'Cambridge International Global Scholars Award and Cambridge International Excellence Award') LIMIT 1;
